// File: frtdao.sol


pragma solidity ^0.8.28;



/**
 * @title FRTDAO
 * @notice ERC20 governance/reward token for FRT DAO.
 * @dev Premints 2_000_000 tokens (18 decimals) to `initialOwner`.
 *      After deploy, owner calls `setTreasury` with the Treasury contract address;
 *      only that address may mint/burn. Staking calls Treasury.mint, which mints here.
 *
 *      Pancake buy/sell is allowlist-only: once `pancakePair` is set, transfers
 *      into or out of the pair require `isSwapAllowed[user] == true`. Default is
 *      blocked for everyone; owner adds users via `setSwapAllowed`.
 */
contract FRTDAO is ERC20, Ownable {
    /// @notice Authorized minter/burner (expected to be the Treasury contract).
    address public treasury;

    /// @notice PancakeSwap V2 pair used to detect buy/sell transfers.
    address public pancakePair;

    /// @notice Addresses allowed to buy/sell via `pancakePair`. Default: false (blocked).
    mapping(address => bool) public isSwapAllowed;

    error ZeroAddress();
    error OnlyTreasury();
    error SwapNotAllowed();
    error InvalidAmount();

    event TreasuryUpdated(address indexed previousTreasury, address indexed newTreasury);
    event PancakePairUpdated(address indexed previousPair, address indexed newPair);
    event SwapAllowedUpdated(address indexed account, bool allowed);
    event TokensBurned(address indexed from, uint256 amount);

    modifier onlyTreasury() {
        if (msg.sender != treasury) revert OnlyTreasury();
        _;
    }

    /**
     * @param initialOwner Receives ownership and the 2_000_000 token premint.
     */
    constructor(address initialOwner) ERC20("FORESIGHT", "FRT") Ownable(initialOwner) {
        if (initialOwner == address(0)) revert ZeroAddress();
        _mint(initialOwner, 2_000_000 ether);
    }

    /**
     * @notice Set or update the Treasury contract authorized to mint/burn.
     * @dev Call after both FRTDAO and Treasury are deployed.
     */
    function setTreasury(address treasury_) external onlyOwner {
        if (treasury_ == address(0)) revert ZeroAddress();
        address previous = treasury;
        treasury = treasury_;
        isSwapAllowed[treasury_] = true;
        emit TreasuryUpdated(previous, treasury_);
    }

    /**
     * @notice Set the PancakeSwap V2 pair used for buy/sell allowlist checks.
     * @dev Pass address(0) to disable pair-based swap checks.
     */
    function setPancakePair(address pair_) external onlyOwner {
        address previous = pancakePair;
        pancakePair = pair_;
        emit PancakePairUpdated(previous, pair_);
    }

    /**
     * @notice Allow or revoke multiple addresses for Pancake buy/sell.
     */
    function setBatch(address[] calldata accounts, bool allowed) external onlyOwner {
        uint256 length = accounts.length;
        for (uint256 i; i < length; ++i) {
